(() => {
  'use strict';
  const M = window.AquaModel, KEY = 'fusion-aquafleet-crm-v1';
  let state = M.seed(), persistence = true, restoreWarning = false;
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const saved = JSON.parse(raw);
      if (saved.version !== 1 || !['customers', 'vehicles', 'drivers', 'sources', 'partners', 'trips', 'receipts', 'ledger', 'expenses'].every(k => Array.isArray(saved[k])) || !saved.vehicles.length || !saved.sources.length || !saved.trips.every(t => M.STATUSES.includes(t.status) && saved.customers.some(c => c.id === t.customer) && saved.vehicles.some(v => v.id === t.vehicle) && saved.drivers.some(d => d.id === t.driver) && saved.sources.some(s => s.id === t.source))) throw new Error('Invalid demo data');
      state = saved;
    }
  } catch { restoreWarning = true; }
  const app = document.querySelector('#app'), dialog = document.querySelector('#dialog');
  const routes = ['Dashboard', 'Trips', 'Customers', 'Vehicles', 'Drivers', 'Water Source', 'Payments', 'Expenses', 'Partners', 'Reports'];
  let view = routes.find(r => slug(r) === location.hash.slice(1)) || 'Dashboard', reportTab = 'Fleet Performance', paymentFilter = 'All', sourceFilter = 'S1';
  let filters = { q: '', status: '', vehicle: '', driver: '', customer: '', date: '', paymentType: '', month: M.MONTH, category: '' };
  let toastTimer, returnFocus;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const number = value => Number(value).toLocaleString('en-AE', { maximumFractionDigits: 2 });
  const money = value => 'AED ' + number(value);
  const litres = value => number(value) + ' L';
  const date = value => new Date(value + 'T12:00:00Z').toLocaleDateString('en-GB', { day: '2-digit', month: 'short' });
  const customer = id => state.customers.find(x => x.id === id);
  const vehicle = id => state.vehicles.find(x => x.id === id);
  const driver = id => state.drivers.find(x => x.id === id);
  const source = id => state.sources.find(x => x.id === id);
  const trip = id => state.trips.find(x => x.id === id);
  function slug(label) { return label.toLowerCase().replaceAll(' ', '-'); }
  const paths = {
    Dashboard: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    Trips: '<path d="M4 6h12M13 3l3 3-3 3M20 18H8m3-3-3 3 3 3"/><circle cx="4" cy="18" r="2"/><circle cx="20" cy="6" r="2"/>',
    Customers: '<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m3 11v-3a6 6 0 0 0-3-5"/>',
    Vehicles: '<path d="M3 7h12v10H3zM15 10h4l3 4v3h-7M6 7V5h6v2"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
    Drivers: '<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2M8 7h8"/>',
    'Water Source': '<path d="M12 3C9 8 5 11 5 15a7 7 0 0 0 14 0c0-4-4-7-7-12Z"/><path d="M8 15c2-2 6 2 8 0"/>',
    Payments: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M6 15h4"/>',
    Expenses: '<path d="M6 3h12v18l-3-2-3 2-3-2-3 2ZM9 7h6m-6 4h6m-6 4h3"/>',
    Partners: '<path d="m3 12 5-5 4 2 4-2 5 5-7 7-4-2-3-3m-2-2 5-5m5 4-3-2-3 3 2 2 2-2m-2 6 2-2"/>',
    Reports: '<path d="M3 3v18h18M7 17v-5m5 5V7m5 10v-8"/>',
    plus: '<path d="M12 5v14M5 12h14"/>',
    menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
    close: '<path d="m6 6 12 12M6 18 18 6"/>',
    arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
    fuel: '<path d="M4 21V4h10v17M2 21h14M4 8h10m0 4h3v5a2 2 0 0 0 4 0V9l-3-3"/>',
    clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    profit: '<path d="m3 17 6-6 4 4 8-10m-6 0h6v6"/>',
    download: '<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>'
  };
  function icon(name) { return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.Reports}</svg>`; }
  function button(label, action, id = '', style = '', symbol = '') { return `<button class="btn ${style}" data-action="${action}" data-id="${esc(id)}" type="button">${symbol ? icon(symbol) : ''}${esc(label)}</button>`; }
  function link(label, action, id) { return `<button class="text-button" type="button" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`; }
  function badge(label) {
    const tone = ['Completed', 'Paid', 'Available', 'Recharge'].includes(label) ? 'good' : ['Credit', 'Assigned', 'In Transit', 'Loading', 'Delivered', 'On Trip'].includes(label) ? 'blue' : ['Partially Paid', 'Scheduled', 'Maintenance', 'Outstanding', 'Cash'].includes(label) ? 'warn' : label === 'Overdue' ? 'bad' : '';
    return `<span class="badge ${tone}"><i class="dot"></i>${esc(label)}</span>`;
  }
  function kpi(label, value, note = '', symbol = 'Reports', highlight = false, cash = false) { return `<div class="kpi ${highlight ? 'highlight' : ''}"><div class="kpi-label">${esc(label)}${icon(symbol)}</div><div class="kpi-value">${cash ? '<span class="currency">AED</span>' : ''}${esc(value)}</div><p class="kpi-note">${esc(note)}</p></div>`; }
  function panel(title, body, action = '', subtitle = '') { return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle ? `<p class="sub">${subtitle}</p>` : ''}</div>${action}</div>${body}</section>`; }
  function table(headers, rows, label, foot = '') { return `<div class="table-wrap" role="region" aria-label="${esc(label)}" tabindex="0"><table><thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.join('') : `<tr><td colspan="${headers.length}"><div class="empty">No records match these filters.</div></td></tr>`}</tbody></table></div>${foot ? `<div class="table-foot">${foot}</div>` : ''}`; }
  function options(rows, selected, label = x => x.name, all = '') { return (all ? `<option value="">${esc(all)}</option>` : '') + rows.map(x => `<option value="${esc(x.id)}" ${selected === x.id ? 'selected' : ''}>${esc(label(x))}</option>`).join(''); }
  function filterSelect(label, key, rows, all) { return `<label>${label}<select data-filter="${key}">${options(rows, filters[key], x => x.name, all)}</select></label>`; }
  function fact(label, value) { return `<div class="fact"><dt>${esc(label)}</dt><dd>${value}</dd></div>`; }
  function facts(rows) { return `<dl class="facts">${rows.map(([key, value]) => fact(key, value)).join('')}</dl>`; }
  function tripRows(rows, compact = false) { return rows.map(t => `<tr><td>${link(t.id, 'trip-detail', t.id)}<span class="cell-sub">${date(t.date)} · ${esc(t.time)}</span></td><td><span class="cell-main">${esc(customer(t.customer).name)}</span><span class="cell-sub">${esc(t.destination)}</span></td><td>${esc(vehicle(t.vehicle).plate)}<span class="cell-sub">${esc(driver(t.driver).name)}</span></td><td class="num">${litres(t.quantity)}</td><td class="num">${money(t.amount)}${!compact ? `<span class="cell-sub">${esc(t.paymentType)} · ${esc(M.paymentStatus(t))}</span>` : ''}</td><td>${badge(t.status)}</td></tr>`); }
  function tripsTable(rows, compact = false) { return table(['Trip / time', 'Customer / destination', 'Vehicle / driver', 'Quantity', 'Charge', 'Status'], tripRows(rows, compact), 'Trip list', `${rows.length} trip${rows.length === 1 ? '' : 's'} · Select a trip number to open its operating record`); }
  function fleetChart(kind = 'fuel') {
    const values = state.vehicles.map(v => ({ plate: v.plate.split(' ').slice(-2).join(' '), prev: M.metrics(state, M.PREVIOUS, t => t.vehicle === v.id)[kind === 'fuel' ? 'litres' : 'trips'], now: M.metrics(state, M.MONTH, t => t.vehicle === v.id)[kind === 'fuel' ? 'litres' : 'trips'] }));
    const max = Math.max(1, ...values.flatMap(v => [v.prev, v.now]));
    return `<div class="chart-legend"><span><i class="legend-dot muted"></i>September · full month</span><span><i class="legend-dot"></i>October · to 05 Oct</span></div><div class="bar-chart" role="img" aria-label="${esc(values.map(v => `${v.plate}: September ${v.prev}, October ${v.now}${kind === 'fuel' ? ' litres' : ' trips'}`).join('; '))}">${values.map(v => `<div class="bar-group"><div class="bar previous" style="height:${v.prev / max * 90}%"><span class="bar-value">${number(v.prev)}</span></div><div class="bar" style="height:${v.now / max * 90}%"><span class="bar-value">${number(v.now)}</span></div></div>`).join('')}</div><div class="chart-labels">${values.map(v => `<span>${esc(v.plate)}</span>`).join('')}</div>`;
  }
  function revenueChart() {
    const months = [M.PREVIOUS, M.MONTH], totals = months.map(m => M.metrics(state, m));
    const max = Math.max(1, ...totals.flatMap(m => [m.revenue, m.operating]));
    return `<div class="chart-legend"><span><i class="legend-dot"></i>Revenue</span><span><i class="legend-dot muted"></i>Operating expenses</span></div><div class="bar-chart" role="img" aria-label="${esc(totals.map((m, i) => `${months[i]} revenue ${money(m.revenue)}, expenses ${money(m.operating)}`).join('; '))}">${totals.map(m => `<div class="bar-group"><div class="bar" style="height:${m.revenue / max * 85}%"><span class="bar-value">${number(m.revenue)}</span></div><div class="bar previous" style="height:${m.operating / max * 85}%"><span class="bar-value">${number(m.operating)}</span></div></div>`).join('')}</div><div class="chart-labels"><span>September</span><span>October · to 05 Oct</span></div>`;
  }
  function cashCredit() {
    const rows = state.trips.filter(t => t.date.startsWith(M.MONTH) && M.delivered(t)), cash = M.sum(rows.filter(t => t.paymentType === 'Cash'), t => t.amount), credit = M.sum(rows.filter(t => t.paymentType === 'Credit'), t => t.amount), total = cash + credit;
    return `<div class="split-labels"><span>Cash billing <strong>${money(cash)}</strong></span><span>Credit <strong>${money(credit)}</strong></span></div><div class="split-meter" role="img" aria-label="Cash billing ${money(cash)}, credit billing ${money(credit)}"><span style="width:${total ? cash / total * 100 : 0}%"></span><span style="width:${total ? credit / total * 100 : 0}%"></span></div><p class="muted-note">Billing mix for delivered trips. Credit collections are tracked separately.</p>`;
  }
  function dashboard() {
    const m = M.metrics(state), today = state.trips.filter(t => t.date === M.TODAY).sort((a, b) => b.time.localeCompare(a.time));
    const credit = M.sum(state.trips.filter(t => t.paymentType === 'Credit'), M.outstanding), balance = M.sum(state.sources, s => M.sourceBalance(state, s.id));
    return `<div class="kpi-grid">${kpi("Today's Trips", today.length, '05 October · dispatch queue', 'Trips')}${kpi('Trips This Month', m.trips, `${m.completed} completed · October to date`, 'clock')}${kpi('Active Vehicles', state.vehicles.filter(v => !v.maintenance).length, `${state.vehicles.filter(v => M.vehicleStatus(state, v.id) === 'Available').length} available for assignment`, 'Vehicles')}${kpi('Monthly Revenue', number(m.revenue), 'Recognized on delivery', 'Payments', false, true)}${kpi('Outstanding Credit', number(credit), 'All delivered credit invoices', 'Customers', false, true)}${kpi('Fuel Cost', number(m.fuel), `${litres(m.litres)} recorded this month`, 'fuel', false, true)}${kpi('Water Source Balance', number(balance), 'Across 2 prepaid source accounts', 'Water Source', false, true)}${kpi('Net Profit', number(m.profit), 'Revenue less actual operating costs', 'profit', true, true)}</div>
    <div class="grid-2">${panel("Today's trips", tripsTable(today, true), button('All trips', 'nav', 'Trips', 'ghost', 'arrow'), 'The live movement of your water deliveries')}${panel('Fleet at a glance', `<div class="panel-body"><div class="fleet-list">${state.vehicles.map(v => { const vm = M.metrics(state, M.MONTH, t => t.vehicle === v.id); return `<div><div class="fleet-row"><div class="tanker-icon">${icon('Vehicles')}</div><div class="fleet-info">${link(v.plate, 'vehicle-detail', v.id)}<p class="cell-sub">${esc(driver(v.driver).name)} · ${litres(v.capacity)}</p></div>${badge(M.vehicleStatus(state, v.id))}</div><div class="fleet-meta"><span>${vm.trips} trips this month</span><span>${money(vm.profit)} net</span></div><div class="meter"><span style="width:${vm.revenue ? Math.max(0, Math.min(100, vm.profit / vm.revenue * 100)) : 0}%"></span></div></div>`; }).join('')}</div><div class="account-callout"><p class="cell-sub">Government source · ${esc(source('S1').account)}</p><div><strong>${money(M.sourceBalance(state, 'S1'))}</strong>${button('Account', 'nav', 'Water Source', 'ghost', 'arrow')}</div>${M.sourceBalance(state, 'S1') < 1000 ? '<p class="notice">Low balance · recharge required below AED 1,000.</p>' : '<p class="cell-sub">Healthy balance · recharge alert below AED 1,000</p>'}</div></div>`)}</div>
    <div class="grid-equal">${panel('Revenue vs expenses', `<div class="panel-body">${revenueChart()}</div>`, '', 'September and October · AED')}${panel('Fuel consumption by tanker', `<div class="panel-body">${fleetChart()}<p class="muted-note">Recorded litres. October is a partial month; compare totals with period length in mind.</p></div>`, button('Fleet report', 'report-nav', 'Fuel Report', 'ghost', 'arrow'))}</div>
    <div class="grid-equal">${panel('Cash vs credit', `<div class="panel-body">${cashCredit()}</div>`)}${panel('Trips by vehicle', `<div class="panel-body">${fleetChart('trips')}</div>`)}</div>
    <div class="banner"><div><h2>A delivery, connected from source to collection.</h2><p>Follow TR-1058: 5,000 L → AED 550 revenue → AED 345 cost → AED 205 profit.</p></div>${button('Open walkthrough', 'trip-detail', 'TR-1058', '', 'arrow')}</div>`;
  }
  function tripsView() {
    const filtered = state.trips.filter(t => (!filters.q || [t.id, customer(t.customer).name, t.destination, vehicle(t.vehicle).plate, t.notes].join(' ').toLowerCase().includes(filters.q.toLowerCase())) && ['status', 'vehicle', 'driver', 'customer', 'paymentType'].every(k => !filters[k] || t[k] === filters[k]) && (!filters.date || t.date === filters.date)).sort((a, b) => b.date.localeCompare(a.date) || b.time.localeCompare(a.time));
    return panel('Dispatch register', `<div class="filters"><label class="search">Search trips<input type="search" data-filter="q" aria-label="Search trips" placeholder="Trip, customer, plate or destination" value="${esc(filters.q)}"></label>${filterSelect('Status', 'status', M.STATUSES.map(x => ({ id: x, name: x })), 'All statuses')}${filterSelect('Vehicle', 'vehicle', state.vehicles.map(x => ({ id: x.id, name: x.plate })), 'All vehicles')}${filterSelect('Driver', 'driver', state.drivers, 'All drivers')}${filterSelect('Customer', 'customer', state.customers, 'All customers')}<label>Date<input type="date" data-filter="date" value="${esc(filters.date)}"></label>${filterSelect('Payment type', 'paymentType', ['Cash', 'Credit'].map(x => ({ id: x, name: x })), 'Cash & credit')}${button('Clear', 'clear-filters', '', 'small')}</div>${tripsTable(filtered)}`, '', 'Assign, load, dispatch, deliver and close every water trip');
  }
  function customersView() {
    const rows = state.customers.filter(c => !filters.q || [c.name, c.location, c.contact].join(' ').toLowerCase().includes(filters.q.toLowerCase()));
    return panel('Customer accounts', `<div class="filters"><label class="search">Search customers<input type="search" aria-label="Search customers" data-filter="q" value="${esc(filters.q)}" placeholder="Name, contact or location"></label></div>${table(['Customer', 'Contact / location', 'Terms', 'Trips · Oct', 'Revenue · Oct', 'Outstanding'], rows.map(c => { const m = M.metrics(state, M.MONTH, t => t.customer === c.id); return `<tr><td>${link(c.name, 'customer-detail', c.id)}<span class="cell-sub">${c.id}</span></td><td>${esc(c.contact)} · ${esc(c.phone)}<span class="cell-sub">${esc(c.location)}</span></td><td>${badge(c.type)}<span class="cell-sub">${c.type === 'Credit' ? c.days + ' days · ' + money(c.limit) + ' limit' : 'Payment on delivery'}</span></td><td class="num">${m.trips}</td><td class="num">${money(m.revenue)}</td><td class="num">${money(m.outstanding)}</td></tr>`; }), 'Customer accounts')}`, '', 'Operational history, credit terms and collection balances');
  }
  function vehiclesView() {
    return `<div class="grid-3">${state.vehicles.map(v => { const m = M.metrics(state, M.MONTH, t => t.vehicle === v.id); return `<section class="vehicle-card"><div class="vehicle-head"><div class="tanker-icon">${icon('Vehicles')}</div><div><h2>${esc(v.plate)}</h2><p class="cell-sub">${litres(v.capacity)} · ${esc(v.ownership)}</p></div></div><div class="fleet-meta"><span>${esc(driver(v.driver).name)}</span>${badge(M.vehicleStatus(state, v.id))}</div>${facts([['Trips this month', m.trips], ['Monthly revenue', money(m.revenue)], ['Fuel usage / cost', `${litres(m.litres)} / ${money(m.fuel)}`], ['Operating cost', money(m.operating)]])}<div class="profit-total"><span>Net profit</span><span>${money(m.profit)}</span></div>${button('Vehicle analytics', 'vehicle-detail', v.id, '', 'arrow')}</section>`; }).join('')}</div>${panel('Fuel comparison', `<div class="panel-body">${fleetChart()}</div>${fuelTable()}`, '', 'September full month vs October to 05 Oct · totals, not normalized efficiency')}`;
  }
  function fuelTable() {
    return table(['Vehicle', 'September', 'October · MTD', 'Total change', 'Fuel / trip · Oct', 'Fuel cost / trip'], state.vehicles.map(v => {
      const prev = M.metrics(state, M.PREVIOUS, t => t.vehicle === v.id), now = M.metrics(state, M.MONTH, t => t.vehicle === v.id), fueled = state.trips.filter(t => t.vehicle === v.id && t.date.startsWith(M.MONTH) && t.costsRecorded).length;
      const change = prev.litres ? (now.litres - prev.litres) / prev.litres * 100 : 0;
      return `<tr><td>${link(v.plate, 'vehicle-detail', v.id)}</td><td class="num">${litres(prev.litres)}</td><td class="num">${litres(now.litres)}</td><td class="num">${change > 0 ? '+' : ''}${change.toFixed(1)}%</td><td class="num">${litres(fueled ? M.round(now.litres / fueled) : 0)}</td><td class="num">${money(fueled ? M.round(now.fuel / fueled) : 0)}</td></tr>`;
    }), 'Monthly tanker fuel comparison', 'Per-trip averages use trips with actual fuel recorded. Period lengths differ.');
  }
  function driversView() { return panel('Driver operations', table(['Driver', 'Assigned vehicle', 'Completed · Oct', 'Revenue handled', 'Fuel / trip', 'Driver earned', 'Status'], state.drivers.map(d => { const m = M.metrics(state, M.MONTH, t => t.driver === d.id), fueled = state.trips.filter(t => t.driver === d.id && t.costsRecorded && t.date.startsWith(M.MONTH)).length; return `<tr><td>${link(d.name, 'driver-detail', d.id)}<span class="cell-sub">${esc(d.phone)}</span></td><td>${esc(vehicle(d.vehicle).plate)}</td><td class="num">${m.completed}</td><td class="num">${money(m.revenue)}</td><td class="num">${litres(fueled ? M.round(m.litres / fueled) : 0)}</td><td class="num">${money(m.driver)}</td><td>${badge(M.driverStatus(state, d.id))}</td></tr>`; }), 'Driver operating performance'), '', 'Trip assignments and performance · operational earnings, not payroll'); }
  function waterView() {
    const s = source(sourceFilter), loads = state.ledger.filter(l => l.source === s.id && l.type === 'Load' && l.date.startsWith(M.MONTH)), balance = M.sourceBalance(state, s.id), ledger = state.ledger.filter(l => l.source === s.id).slice().reverse();
    return `<div class="grid-equal">${state.sources.map(x => `<section class="vehicle-card"><div class="vehicle-head"><div class="tanker-icon">${icon('Water Source')}</div><div><h2>${esc(x.name)}</h2><p class="cell-sub">${x.account} · ${esc(x.location)}</p></div></div><p class="kpi-value"><span class="currency">AED</span>${number(M.sourceBalance(state, x.id))}</p><p class="sub">${money(x.rate * 1000)} / 1,000 L · prepaid source balance</p><div class="actions" style="margin-top:14px">${button('View ledger', 'source-select', x.id, 'small')}${button('Recharge', 'recharge', x.id, 'primary small', 'plus')}</div>${M.sourceBalance(state, x.id) < 1000 ? '<p class="notice">Low balance · recharge required below AED 1,000.</p>' : ''}</section>`).join('')}</div><div class="kpi-grid">${kpi('Available Balance', number(balance), s.account, 'Water Source', true, true)}${kpi('Loads This Month', loads.length, 'Posted once at loading', 'Vehicles')}${kpi('Water Purchased', number(M.sum(loads, l => l.quantity)), 'Litres · October to date', 'Water Source')}${kpi('Monthly Spend', number(-M.sum(loads, l => l.amount)), 'Source loads only · AED', 'Expenses', false, true)}</div>${panel(`${esc(s.name)} · account ledger`, table(['Transaction', 'Date', 'Vehicle / trip', 'Quantity', 'Charge / recharge', 'Before', 'After'], ledger.map(l => `<tr><td><span class="cell-main">${l.id}</span><span class="cell-sub">${esc(l.reference)}</span>${badge(l.type)}</td><td>${date(l.date)}<span class="cell-sub">2026</span></td><td>${l.vehicle ? esc(vehicle(l.vehicle).plate) : 'Account recharge'}<span class="cell-sub">${l.trip ? link(l.trip, 'trip-detail', l.trip) : esc(l.notes || '')}</span></td><td class="num">${l.quantity ? litres(l.quantity) : '—'}</td><td class="num">${l.amount > 0 ? '+' : '−'}${money(Math.abs(l.amount))}</td><td class="num">${money(l.before)}</td><td class="num">${money(l.after)}</td></tr>`), 'Water-source running ledger', 'Loading deducts the source charge once. Recharges change prepaid balance, never trip profit.'), button('Recharge account', 'recharge', s.id, 'primary', 'plus'))}`;
  }
  function paymentRows(rows) { return rows.map(t => `<tr><td>${link(customer(t.customer).name, 'customer-detail', t.customer)}</td><td>${link(t.id, 'trip-detail', t.id)}<span class="cell-sub">INV-${t.id.slice(3)}</span></td><td class="num">${money(t.amount)}</td><td class="num">${money(t.paid)}</td><td class="num">${money(M.outstanding(t))}</td><td>${date(t.due)} ${t.due.slice(0, 4)}</td><td>${badge(t.paymentType)}</td><td>${badge(M.paymentStatus(t))}</td><td>${M.outstanding(t) > 0 ? button('Collect', 'collect', t.id, 'small') : 'Closed'}</td></tr>`); }
  function paymentsView() {
    const rows = state.trips.filter(M.delivered).filter(t => paymentFilter === 'All' || ['Cash', 'Credit'].includes(paymentFilter) ? paymentFilter === 'All' || t.paymentType === paymentFilter : paymentFilter === 'Outstanding' ? M.outstanding(t) > 0 : M.paymentStatus(t) === paymentFilter).sort((a, b) => b.date.localeCompare(a.date));
    const all = state.trips.filter(M.delivered), collected = M.sum(state.receipts, r => r.amount);
    return `<div class="grid-equal"><div class="payment-flow"><strong>Cash</strong> · Deliver → Receive payment → Close trip</div><div class="payment-flow"><strong>Credit</strong> · Deliver → Amount due → Receive payment → Close balance</div></div><div class="kpi-grid">${kpi('Total Collected', number(collected), 'All demo payment receipts', 'Payments', false, true)}${kpi('Outstanding', number(M.sum(all, M.outstanding)), 'All delivered invoices', 'Customers', true, true)}${kpi('Overdue', number(M.sum(all.filter(t => M.paymentStatus(t) === 'Overdue'), M.outstanding)), 'As of 05 October 2026', 'clock', false, true)}${kpi('Open Invoices', all.filter(t => M.outstanding(t) > 0).length, 'Partial and unpaid balances', 'Expenses')}</div>${panel('Collections desk', `<div class="tabs" aria-label="Payment filters">${['All', 'Cash', 'Credit', 'Outstanding', 'Paid', 'Overdue'].map(x => `<button type="button" data-action="payment-filter" data-id="${x}" aria-pressed="${paymentFilter === x}">${x}</button>`).join('')}</div>${table(['Customer', 'Trip / invoice', 'Amount', 'Paid', 'Outstanding', 'Due date', 'Type', 'Status', 'Action'], paymentRows(rows), 'Customer collections')}`, '', 'Receipts reduce customer balances immediately; trip revenue stays the same')}${panel('Recent receipts', table(['Receipt', 'Date', 'Customer', 'Trip', 'Amount', 'Reference'], state.receipts.slice(-6).reverse().map(r => `<tr><td>${r.id}</td><td>${date(r.date)}</td><td>${esc(customer(r.customer).name)}</td><td>${link(r.trip, 'trip-detail', r.trip)}</td><td class="num">${money(r.amount)}</td><td>${esc(r.reference)}</td></tr>`), 'Recent payment receipts'))}`;
  }
  function expensesView() {
    const rows = M.expenseRows(state).filter(e => (!filters.vehicle || e.vehicle === filters.vehicle) && (!filters.month || e.date.startsWith(filters.month)) && (!filters.category || e.category === filters.category));
    return panel('Operating cost register', `<div class="filters">${filterSelect('Vehicle', 'vehicle', state.vehicles.map(v => ({ id: v.id, name: v.plate })), 'All vehicles')}<label>Month<input type="month" data-filter="month" value="${esc(filters.month)}"></label>${filterSelect('Category', 'category', ['Fuel', 'Water Source', 'Driver Payment', 'Maintenance', 'Salik/Toll', 'Parking', 'Other'].map(x => ({ id: x, name: x })), 'All categories')}</div>${table(['Date', 'Category', 'Vehicle', 'Trip', 'Amount', 'Description'], rows.map(e => `<tr><td>${date(e.date)}</td><td>${badge(e.category)}</td><td>${esc(vehicle(e.vehicle).plate)}</td><td>${e.trip ? link(e.trip, 'trip-detail', e.trip) : 'Fleet expense'}</td><td class="num">${money(e.amount)}</td><td>${esc(e.description)}</td></tr>`), 'Operating expenses', `${rows.length} actual cost entries · ${money(M.sum(rows, e => e.amount))} total · Trip costs appear once`)}`, button('Add fleet expense', 'expense', '', 'primary', 'plus'), 'Fuel, water and driver costs come from trips; fleet expenses are recorded separately');
  }
  function partnersView() {
    const p = state.partners[0], v = vehicle(p.vehicle), m = M.metrics(state, M.MONTH, t => t.vehicle === v.id), share = M.round(m.profit * p.share);
    return `<div class="banner"><div><h2>Grow the fleet with a clear 50/50 arrangement.</h2><p>One vehicle, shared investment and a transparent split of the actual monthly result.</p></div>${badge('50% partner / 50% company')}</div><div class="grid-equal">${panel('Partnership vehicle', `<div class="panel-body">${facts([['Partner', esc(p.name)], ['Vehicle', link(v.plate, 'vehicle-detail', v.id)], ['Ownership', '50% Partner / 50% Company'], ['Total vehicle investment', money(v.investment)], ['Partner investment', money(v.investment / 2)], ['Company investment', money(v.investment / 2)]])}<p class="muted-note">Illustrative expansion agreement. Splits represent earned profit or loss, not a posted payout.</p></div>`)}${panel('October allocation · to 05 Oct', `<div class="panel-body">${facts([['Revenue', money(m.revenue)], ['Water cost', '−' + money(m.water)], ['Fuel', '−' + money(m.fuel)], ['Driver payments', '−' + money(m.driver)], ['Other / fleet expenses', '−' + money(m.other)]])}<div class="profit-total"><span>Net profit</span><span>${money(m.profit)}</span></div><div class="split-meter"><span style="width:50%"></span><span style="width:50%"></span></div><div class="split-labels"><div>Partner · 50%<br><strong>${money(share)}</strong></div><div>Company · 50%<br><strong>${money(M.round(m.profit - share))}</strong></div></div></div>`)}</div>`;
  }
  function reportsView() {
    const tabs = ['Fleet Performance', 'Fuel Report', 'Customer Report', 'Driver Report', 'Financial Report', 'Government Account'];
    const m = M.metrics(state), month = filters.month || M.MONTH;
    let body;
    if (reportTab === 'Fleet Performance') body = table(['Vehicle', 'Trips', 'Revenue', 'Fuel litres', 'Fuel cost', 'Operating cost', 'Net profit'], state.vehicles.map(v => { const vm = M.metrics(state, month, t => t.vehicle === v.id); return `<tr><td>${link(v.plate, 'vehicle-detail', v.id)}</td><td class="num">${vm.trips}</td><td class="num">${money(vm.revenue)}</td><td class="num">${litres(vm.litres)}</td><td class="num">${money(vm.fuel)}</td><td class="num">${money(vm.operating)}</td><td class="num">${money(vm.profit)}</td></tr>`; }), 'Fleet performance report');
    if (reportTab === 'Fuel Report') body = `<div class="panel-body">${fleetChart()}<p class="muted-note">September vs October to date; total consumption change is not an efficiency improvement.</p></div>${fuelTable()}`;
    if (reportTab === 'Customer Report') body = table(['Customer', 'Trips', 'Revenue', 'Trip contribution', 'Outstanding · all dates', 'Payment behaviour'], state.customers.map(c => { const cm = M.metrics(state, month, t => t.customer === c.id), overdue = state.trips.some(t => t.customer === c.id && M.paymentStatus(t) === 'Overdue'); return `<tr><td>${link(c.name, 'customer-detail', c.id)}</td><td class="num">${cm.trips}</td><td class="num">${money(cm.revenue)}</td><td class="num">${money(cm.profit)}</td><td class="num">${money(cm.outstanding)}</td><td>${badge(overdue ? 'Overdue' : cm.outstanding ? 'Outstanding' : 'Paid')}</td></tr>`; }), 'Customer report');
    if (reportTab === 'Driver Report') body = table(['Driver', 'Trips', 'Completed', 'Revenue', 'Trip contribution', 'Driver payments', 'Fuel / recorded trip'], state.drivers.map(d => { const dm = M.metrics(state, month, t => t.driver === d.id), count = state.trips.filter(t => t.driver === d.id && t.date.startsWith(month) && t.costsRecorded).length; return `<tr><td>${link(d.name, 'driver-detail', d.id)}</td><td class="num">${dm.trips}</td><td class="num">${dm.completed}</td><td class="num">${money(dm.revenue)}</td><td class="num">${money(dm.profit)}</td><td class="num">${money(dm.driver)}</td><td class="num">${litres(count ? M.round(dm.litres / count) : 0)}</td></tr>`; }), 'Driver performance report');
    if (reportTab === 'Financial Report') {
      const fm = M.metrics(state, month), extra = M.sum(state.expenses.filter(e => e.date.startsWith(month)), e => e.amount);
      body = `<div class="panel-body">${facts([['Delivered revenue', money(fm.revenue)], ['Water source consumption', '−' + money(fm.water)], ['Actual fuel', '−' + money(fm.fuel)], ['Driver costs earned', '−' + money(fm.driver)], ['Other trip expenses', '−' + money(fm.other - extra)], ['Gross trip contribution', money(fm.profit + extra)], ['Separate fleet expenses', '−' + money(extra)], ['Total operating expenses', money(fm.operating)], ['Outstanding customer money · all dates', money(fm.outstanding)]])}<div class="profit-total"><span>Net operating profit</span><span>${money(fm.profit)}</span></div><p class="muted-note">Delivered revenue less all actual costs incurred in this period, including loading trips. Estimates and prepaid recharges do not count as expenses. Operational demonstration; VAT, depreciation and accrual accounting are excluded.</p></div>`;
    }
    if (reportTab === 'Government Account') body = table(['Account', 'Opening balance', 'Recharge', 'Consumption', 'Closing balance', 'Loads / litres'], state.sources.map(s => { const before = state.ledger.filter(l => l.source === s.id && l.date.slice(0, 7) < month), ls = state.ledger.filter(l => l.source === s.id && l.date.startsWith(month)), opening = s.opening + M.sum(before, l => l.amount), recharges = M.sum(ls.filter(l => l.amount > 0), l => l.amount), consumption = -M.sum(ls.filter(l => l.amount < 0), l => l.amount); return `<tr><td>${esc(s.account)}<span class="cell-sub">${esc(s.name)}</span></td><td class="num">${money(opening)}</td><td class="num">${money(recharges)}</td><td class="num">${money(consumption)}</td><td class="num">${money(opening + recharges - consumption)}</td><td class="num">${ls.filter(l => l.type === 'Load').length} / ${litres(M.sum(ls, l => l.quantity))}</td></tr>`; }), 'Water-source monthly reconciliation');
    return `<div class="kpi-grid">${kpi('Monthly Revenue', number(m.revenue), 'October · delivered trips', 'Payments', false, true)}${kpi('Operating Expenses', number(m.operating), 'October · actual incurred costs', 'Expenses', false, true)}${kpi('Net Profit', number(m.profit), 'October · after fleet expenses', 'profit', true, true)}${kpi('Outstanding', number(m.outstanding), 'All delivered customer balances', 'Customers', false, true)}</div>${panel('Operations intelligence', `<div class="tabs" aria-label="Report sections">${tabs.map(t => `<button type="button" data-action="report-tab" data-id="${t}" aria-pressed="${reportTab === t}">${t}</button>`).join('')}</div>${reportTab !== 'Fuel Report' ? `<div class="filters"><label>Report month<input type="month" data-filter="month" value="${esc(month)}"></label></div>` : ''}${body}`, button('Export CSV', 'export', '', '', 'download'), esc(reportTab))}`;
  }
  function navigation() { return routes.map(r => `<button type="button" data-action="nav" data-id="${r}" ${view === r ? 'aria-current="page"' : ''}>${icon(r)}${r}</button>`).join(''); }
  const descriptions = { Dashboard: 'Your water delivery operation, at a glance.', Trips: 'Every load, delivery and dirham of cost.', Customers: 'Water requirements, trip history and cash or credit.', Vehicles: 'Three tankers. Every trip, litre and margin accounted for.', Drivers: 'The people keeping your deliveries moving.', 'Water Source': 'Prepaid source accounts, loads and running balances.', Payments: 'Know what is collected, due and overdue.', Expenses: 'Actual operating costs, connected to the fleet.', Partners: 'Shared vehicles. Transparent monthly results.', Reports: 'A clear view of the operation behind the numbers.' };
  function render() {
    const views = { Dashboard: dashboard, Trips: tripsView, Customers: customersView, Vehicles: vehiclesView, Drivers: driversView, 'Water Source': waterView, Payments: paymentsView, Expenses: expensesView, Partners: partnersView, Reports: reportsView };
    const action = view === 'Water Source' ? button('Recharge account', 'recharge', sourceFilter, 'primary', 'plus') : view === 'Expenses' ? button('Add expense', 'expense', '', 'primary', 'plus') : button('New trip', 'new-trip', '', 'primary', 'plus');
    app.innerHTML = `<a class="sr-only" href="#main-content">Skip to content</a><div class="shell"><aside class="sidebar"><div class="brand"><img src="./favicon.svg" alt=""><div><strong>AquaFleet<span style="color:var(--water)">.</span></strong><small>Water transport CRM</small></div></div><p class="nav-label">Operations workspace</p><nav class="nav" aria-label="Main navigation">${navigation()}</nav><div class="sidebar-bottom"><span class="demo-label"><i class="dot"></i>Interactive demo</span><p>Fictional UAE operations.<br>${persistence ? 'Changes saved in this browser.' : 'Changes held in this session.'}</p>${button('Reset demo', 'reset', '', 'ghost small')}<p><a href="/business-software">By Fusion Ventures ↗</a></p></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${button('Menu', 'menu', '', 'mobile-menu small', 'menu')}<span>Operations</span><span aria-hidden="true">/</span><strong>${view}</strong></div><div class="topbar-right"><span class="demo-label"><i class="dot"></i>Demo · UAE</span><span class="sub">05 Oct 2026</span><span class="avatar" aria-label="Demo operator">AK</span></div></header><main id="main-content" class="content" tabindex="-1"><div class="page-head"><div><p class="eyebrow">${view === 'Dashboard' ? 'Monday, 05 October 2026' : 'AquaFleet / ' + view}</p><h1>${view === 'Dashboard' ? 'Operations overview' : view}</h1><p class="sub">${descriptions[view]}</p></div><div class="actions">${action}</div></div>${views[view]()}<footer class="footer-note"><span>Fictional data · AED · Demo date fixed at 05 Oct 2026</span><span>${persistence ? 'Browser-local workspace' : 'Session-only workspace'} · <a href="/business-software">Fusion Ventures portfolio ↗</a></span></footer></main></div></div>`;
  }
  function toast(message) { clearTimeout(toastTimer); document.querySelector('#toast').textContent = message; toastTimer = setTimeout(() => { document.querySelector('#toast').textContent = ''; }, 5500); }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch { persistence = false; toast('Browser storage is unavailable. Changes will last for this session.'); } }
  function mutate(fn) { const before = structuredClone(state); try { const result = fn(); save(); render(); return result; } catch (error) { state = before; throw error; } }
  function openDialog(title, subtitle, body, narrow = false) {
    if (!dialog.open) returnFocus = document.activeElement;
    dialog.className = narrow ? 'narrow' : '';
    dialog.innerHTML = `<div class="dialog-head"><div><p class="eyebrow">AquaFleet / operations</p><h2 id="dialog-title">${esc(title)}</h2><p class="sub">${subtitle}</p></div><button type="button" class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;
    if (!dialog.open) dialog.showModal();
    dialog.scrollTop = 0;
  }
  function closeDialog() { dialog.close(); }
  dialog.addEventListener('close', () => { if (returnFocus?.isConnected) returnFocus.focus(); else document.querySelector('.page-head .btn')?.focus(); });
  function field(label, name, value = '', type = 'text', extra = '', wide = false) { return `<label class="field ${wide ? 'wide' : ''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`; }
  function selectField(label, name, rows, selected, labelFn = x => x.name) { return `<label class="field">${label}<select name="${name}" required>${options(rows, selected, labelFn)}</select></label>`; }
  function formEnd(label) { return `<div class="form-error" role="alert"></div><div class="dialog-actions">${button('Cancel', 'close')}<button type="submit" class="btn primary">${label}</button></div></form>`; }
  function newTripForm() {
    const available = state.vehicles.filter(v => M.vehicleStatus(state, v.id) === 'Available'), drivers = state.drivers.filter(d => M.driverStatus(state, d.id) === 'Available'), v = available[0];
    if (!v || !drivers.length) { openDialog('No tankers available', 'Complete the current assignments to release a vehicle and driver.', `<p class="notice">Every tanker or driver is currently assigned. Open Trips to finish the existing deliveries.</p><div class="dialog-actions">${button('Open trips', 'nav', 'Trips', 'primary')}</div>`, true); return; }
    openDialog('Create a water trip', 'Assign a tanker and driver. The source account is debited only when loading begins.', `<form data-form="trip"><div class="form-grid">${selectField('Customer', 'customer', state.customers, 'CU-101')}${selectField('Payment type', 'paymentType', ['Cash', 'Credit'].map(x => ({ id: x, name: x })), 'Credit')}${selectField('Available vehicle', 'vehicle', available, v.id, x => `${x.plate} · ${litres(x.capacity)}`)}${selectField('Driver', 'driver', drivers, v.driver)}${selectField('Water source', 'source', state.sources, 'S1')}${field('Water quantity · litres', 'quantity', 5000, 'number', `required min="1" max="${v.capacity}" step="1"`)}${field('Delivery location', 'destination', customer('CU-101').location, 'text', 'required maxlength="160"', true)}${field('Date', 'date', M.TODAY, 'date', `required min="${M.TODAY}"`)}${field('Time', 'time', '14:30', 'time', 'required')}${field('Customer charge · AED', 'amount', 550, 'number', 'required min="0.01" step="0.01"')}${field('Fuel estimate · AED', 'fuelEstimate', 95, 'number', 'required min="0" step="0.01"')}<label class="field wide">Notes<textarea name="notes" maxlength="800" placeholder="Site access, loading or delivery instructions"></textarea></label></div><p id="trip-estimate" class="notice">Estimated source charge: ${money(210)}. Fuel estimate is excluded from actual expenses.</p>${formEnd('Create & assign trip')}`);
  }
  function tripDetail(id) {
    const t = trip(id), c = customer(t.customer), next = M.STATUSES[M.STATUSES.indexOf(t.status) + 1];
    const flow = M.STATUSES.map((status, i) => `<span class="${i <= M.STATUSES.indexOf(t.status) ? 'active' : ''}">${i + 1}. ${status}</span>${i < 5 ? '<b aria-hidden="true">→</b>' : ''}`).join('');
    const actions = `${t.status === 'Loading' && !t.costsRecorded ? button('Record fuel & costs', 'costs', t.id, 'primary', 'fuel') : ''}${next ? button(next === 'Assigned' ? 'Assign vehicle' : next === 'Loading' ? 'Load water & debit source' : next === 'In Transit' ? 'Dispatch tanker' : next === 'Delivered' ? 'Confirm delivery' : 'Complete trip', 'advance', t.id, 'primary', 'arrow') : badge('Completed')}${M.outstanding(t) > 0 ? button('Record collection', 'collect', t.id) : ''}`;
    openDialog(t.id + ' · Water delivery', `${esc(c.name)} · ${date(t.date)} 2026 at ${esc(t.time)} · ${badge(t.status)}`, `<div class="flow-strip" aria-label="Trip lifecycle">${flow}</div><div class="detail-grid">${panel('Operating record', `<div class="panel-body">${facts([['Customer', link(c.name, 'customer-detail', c.id)], ['Vehicle', link(vehicle(t.vehicle).plate, 'vehicle-detail', t.vehicle)], ['Driver', link(driver(t.driver).name, 'driver-detail', t.driver)], ['Pickup source', esc(source(t.source).name)], ['Delivery location', esc(t.destination)], ['Quantity', litres(t.quantity)], ['Rate / 1,000 L', money(t.rate)]])}</div>`)}${panel('Revenue & collection', `<div class="panel-body">${facts([['Customer charge', money(t.amount)], ['Revenue recognized', money(M.delivered(t) ? t.amount : 0)], ['Paid amount', money(t.paid)], ['Outstanding', money(M.outstanding(t))], ['Payment type', badge(t.paymentType)], ['Due date', `${date(t.due)} ${t.due.slice(0, 4)}`], ['Payment status', badge(M.paymentStatus(t))]])}<p class="muted-note">${t.paymentType === 'Cash' ? 'Cash trips require full collection before closing.' : 'Credit trips can close with a balance outstanding. Receipts update the customer account.'}</p></div>`)}</div><div class="detail-grid">${panel('Actual costs', `<div class="panel-body">${facts([['Water / source cost', t.loaded ? money(t.waterCost) : 'Not loaded · estimate ' + money(t.waterCost)], ['Fuel', `${money(t.fuelCost)} · ${litres(t.fuelLitres)}`], ['Driver payment earned', money(t.driverCost)], ['Other trip expenses', money(t.otherCost)], ['Total operating cost', money(M.cost(t))]])}<p class="muted-note">Fuel estimate: ${money(t.fuelEstimate)}. Actual fuel, driver and other costs are recorded while loading.</p></div>`)}${panel('Trip profitability', `<div class="panel-body">${facts([['Delivered revenue', money(M.delivered(t) ? t.amount : 0)], ['Water cost', '−' + money(t.loaded ? t.waterCost : 0)], ['Fuel cost', '−' + money(t.fuelCost)], ['Driver cost', '−' + money(t.driverCost)], ['Other expenses', '−' + money(t.otherCost)]])}<div class="profit-total"><span>${M.delivered(t) ? 'Net trip profit' : 'Contribution to date'}</span><span>${money(M.profit(t))}</span></div></div>`)}</div>${t.notes ? `<div class="notes"><strong>Delivery notes</strong><p>${esc(t.notes)}</p></div>` : ''}${!M.delivered(t) ? '<p class="muted-note">Customer charge becomes revenue and a balance due on delivery. Until then, incurred loading costs reduce contribution to date.</p>' : ''}<div class="form-error" role="alert"></div><div class="dialog-actions">${actions}</div>`);
  }
  function costsForm(id) {
    const t = trip(id);
    openDialog('Record actual trip costs', `${id} · Loading · estimates will be replaced by these actual costs.`, `<form data-form="costs" data-id="${id}"><div class="form-grid">${field('Fuel quantity · litres', 'fuelLitres', 32, 'number', 'required min="0" step="0.01"')}${field('Fuel cost · AED', 'fuelCost', t.fuelEstimate, 'number', 'required min="0" step="0.01"')}${field('Driver payment · AED', 'driverCost', t.quantity > 5000 ? 60 : 40, 'number', 'required min="0" step="0.01"')}${field('Other trip expenses · AED', 'otherCost', 0, 'number', 'required min="0" step="0.01"')}</div><p class="muted-note">Source charge ${money(t.waterCost)} is already in the ledger. Saving these costs updates the trip, tanker, driver and expense reports once.</p>${formEnd('Save actual costs')}`, true);
  }
  function customerDetail(id) {
    const c = customer(id), m = M.metrics(state, M.MONTH, t => t.customer === id), rows = state.trips.filter(t => t.customer === id).sort((a, b) => b.date.localeCompare(a.date)), receipts = state.receipts.filter(r => r.customer === id);
    openDialog(c.name, `${c.id} · ${badge(c.type)} ${c.type === 'Credit' ? ' · ' + c.days + ' day terms' : ' · Payment on delivery'}`, `<div class="kpi-grid">${kpi('Outstanding', number(m.outstanding), 'All delivered trips', 'Customers', true, true)}${kpi('Monthly Revenue', number(m.revenue), 'October · delivered', 'Payments', false, true)}${kpi('Trips This Month', m.trips, 'October to date', 'Trips')}</div><div class="detail-grid">${panel('Account overview', `<div class="panel-body">${facts([['Contact person', esc(c.contact)], ['Mobile', esc(c.phone)], ['WhatsApp', esc(c.phone)], ['Location', esc(c.location)], ['Credit days', c.type === 'Credit' ? c.days : 0], ['Credit limit', c.type === 'Credit' ? money(c.limit) : 'Cash account'], ['Total delivered revenue', money(M.sum(rows.filter(M.delivered), t => t.amount))], ['Monthly trip contribution', money(m.profit)]])}${c.type === 'Credit' && m.outstanding >= c.limit ? '<p class="notice">Credit limit reached. Review collections before assigning further credit deliveries.</p>' : ''}</div>`)}${panel('Collection overview', `<div class="panel-body">${facts([['Total received', money(M.sum(receipts, r => r.amount))], ['Outstanding', money(m.outstanding)], ['Overdue', money(M.sum(rows.filter(t => M.paymentStatus(t) === 'Overdue'), M.outstanding))]])}<p class="notes" style="margin-top:18px">${esc(c.notes)}</p></div>`)}</div>${panel('Trip history', tripsTable(rows))}${panel('Payments', table(['Receipt', 'Date', 'Trip', 'Received', 'Reference'], receipts.map(r => `<tr><td>${r.id}</td><td>${date(r.date)}</td><td>${link(r.trip, 'trip-detail', r.trip)}</td><td class="num">${money(r.amount)}</td><td>${esc(r.reference)}</td></tr>`), 'Customer payment history'))}`);
  }
  function vehicleDetail(id) {
    const v = vehicle(id), m = M.metrics(state, M.MONTH, t => t.vehicle === id), prev = M.metrics(state, M.PREVIOUS, t => t.vehicle === id), rows = state.trips.filter(t => t.vehicle === id).sort((a, b) => b.date.localeCompare(a.date)), fueled = rows.filter(t => t.date.startsWith(M.MONTH) && t.costsRecorded).length;
    openDialog(v.plate + ' · Vehicle analytics', `${litres(v.capacity)} · ${esc(driver(v.driver).name)} · ${esc(v.ownership)} · ${badge(M.vehicleStatus(state, id))}`, `<div class="kpi-grid">${kpi('Trips This Month', m.trips, 'October to date', 'Trips')}${kpi('Revenue', number(m.revenue), 'Recognized deliveries', 'Payments', false, true)}${kpi('Fuel Cost', number(m.fuel), litres(m.litres) + ' recorded', 'fuel', false, true)}${kpi('Water Cost', number(m.water), 'Loaded source charges', 'Water Source', false, true)}${kpi('Driver Cost', number(m.driver), 'Trip earnings', 'Drivers', false, true)}${kpi('Net Profit', number(m.profit), 'After all vehicle expenses', 'profit', true, true)}</div>${panel('Fuel monitoring · September vs October', `<div class="panel-body">${facts([['September · full month', litres(prev.litres)], ['October · to 05 Oct', litres(m.litres)], ['Consumption change', `${prev.litres ? ((m.litres - prev.litres) / prev.litres * 100).toFixed(1) : '0'}%`], ['Fuel / recorded trip', litres(fueled ? M.round(m.litres / fueled) : 0)], ['Average fuel cost / trip', money(fueled ? M.round(m.fuel / fueled) : 0)], ['Other / fleet expenses', money(m.other)]])}<div class="meter" style="margin-top:16px"><span style="width:${Math.min(100, m.litres / Math.max(1, m.litres, prev.litres) * 100)}%"></span></div><p class="muted-note">Monthly litres depend on the number of trips and period length. Fuel per trip is an operational indicator; distance-based efficiency requires odometer readings.</p></div>`)}${panel('Vehicle trip register', tripsTable(rows))}`);
  }
  function driverDetail(id) {
    const d = driver(id), m = M.metrics(state, M.MONTH, t => t.driver === id), rows = state.trips.filter(t => t.driver === id).sort((a, b) => b.date.localeCompare(a.date)), fueled = rows.filter(t => t.date.startsWith(M.MONTH) && t.costsRecorded).length;
    openDialog(d.name + ' · Driver operations', `${esc(d.phone)} · ${badge(M.driverStatus(state, id))}`, `<div class="kpi-grid">${kpi('Trips This Month', m.trips, `${m.completed} completed`, 'Trips')}${kpi('Driver Payment Earned', number(m.driver), 'October actual trip costs', 'Drivers', false, true)}${kpi('Fuel / Recorded Trip', number(fueled ? M.round(m.litres / fueled) : 0), 'Litres · October', 'fuel')}</div>${panel('Current assignment', `<div class="panel-body">${facts([['Default vehicle', link(vehicle(d.vehicle).plate, 'vehicle-detail', d.vehicle)], ['Current trip', state.trips.filter(t => t.driver === id && !['Scheduled', 'Completed'].includes(t.status)).map(t => link(t.id, 'trip-detail', t.id)).join(' ') || 'Available for assignment'], ['Revenue handled · Oct', money(m.revenue)], ['Trip contribution · Oct', money(m.profit)]])}</div>`)}${panel('Recent trips', tripsTable(rows))}<p class="muted-note">Fuel per trip is indicative performance, not litres per kilometre. Earned driver payments do not represent payroll disbursements.</p>`);
  }
  function rechargeForm(id) { openDialog('Recharge source account', `${esc(source(id).name)} · Current balance ${money(M.sourceBalance(state, id))}`, `<form data-form="recharge" data-id="${id}"><div class="form-grid">${field('Date', 'date', M.TODAY, 'date', `required max="${M.TODAY}"`)}${field('Amount · AED', 'amount', 2000, 'number', 'required min="0.01" step="0.01"')}${field('Reference', 'reference', '', 'text', 'required maxlength="80"', true)}<label class="field wide">Notes<textarea name="notes" maxlength="500" placeholder="Recharge details"></textarea></label></div><p class="muted-note">Demo credit only. This changes the prepaid balance and ledger; it does not change trip expenses.</p>${formEnd('Post recharge')}`, true); }
  function collectionForm(id) { const t = trip(id); openDialog('Record customer collection', `${id} · ${esc(customer(t.customer).name)} · Balance ${money(M.outstanding(t))}`, `<form data-form="collect" data-id="${id}"><div class="form-grid">${field('Collection · AED', 'amount', M.outstanding(t), 'number', `required min="0.01" step="0.01" max="${M.outstanding(t)}"`)}${field('Date', 'date', M.TODAY, 'date', `required min="${t.date}" max="${M.TODAY}"`)}${field('Receipt reference', 'reference', '', 'text', 'required maxlength="80"', true)}</div><p class="muted-note">Partial collections are supported. This simulated receipt updates the customer balance; it does not add revenue again.</p>${formEnd('Save collection')}`, true); }
  function expenseForm() { openDialog('Add a fleet expense', 'Vehicle-level cost. Trip fuel, water and driver costs are recorded in the trip workflow.', `<form data-form="expense"><div class="form-grid">${selectField('Vehicle', 'vehicle', state.vehicles, 'V1', v => v.plate)}${selectField('Category', 'category', ['Maintenance', 'Salik/Toll', 'Parking', 'Other'].map(x => ({ id: x, name: x })), 'Maintenance')}${field('Date', 'date', M.TODAY, 'date', `required max="${M.TODAY}"`)}${field('Amount · AED', 'amount', '', 'number', 'required min="0.01" step="0.01"')}${field('Description', 'description', '', 'text', 'required maxlength="200"', true)}</div>${formEnd('Save fleet expense')}`, true); }
  function exportReport() {
    const month = filters.month || M.MONTH;
    let rows;
    if (reportTab === 'Fuel Report') rows = [['Vehicle', 'September litres', 'October MTD litres', 'Change percent'], ...state.vehicles.map(v => { const a = M.metrics(state, M.PREVIOUS, t => t.vehicle === v.id), b = M.metrics(state, M.MONTH, t => t.vehicle === v.id); return [v.plate, a.litres, b.litres, a.litres ? M.round((b.litres - a.litres) / a.litres * 100) : 0]; })];
    else if (reportTab === 'Customer Report') rows = [['Customer', 'Month', 'Trips', 'Revenue AED', 'Trip contribution AED', 'Outstanding all dates AED'], ...state.customers.map(c => { const m = M.metrics(state, month, t => t.customer === c.id); return [c.name, month, m.trips, m.revenue, m.profit, m.outstanding]; })];
    else if (reportTab === 'Driver Report') rows = [['Driver', 'Month', 'Trips', 'Completed', 'Revenue AED', 'Trip contribution AED', 'Driver earnings AED', 'Fuel litres'], ...state.drivers.map(d => { const m = M.metrics(state, month, t => t.driver === d.id); return [d.name, month, m.trips, m.completed, m.revenue, m.profit, m.driver, m.litres]; })];
    else if (reportTab === 'Government Account') rows = [['Account', 'Month', 'Opening AED', 'Recharge AED', 'Consumption AED', 'Closing AED'], ...state.sources.map(s => { const opening = s.opening + M.sum(state.ledger.filter(l => l.source === s.id && l.date.slice(0, 7) < month), l => l.amount), entries = state.ledger.filter(l => l.source === s.id && l.date.startsWith(month)), recharge = M.sum(entries.filter(l => l.amount > 0), l => l.amount), consumption = -M.sum(entries.filter(l => l.amount < 0), l => l.amount); return [s.account, month, opening, recharge, consumption, opening + recharge - consumption]; })];
    else if (reportTab === 'Financial Report') { const m = M.metrics(state, month); rows = [['Metric', 'Month', 'AED'], ...[['Delivered revenue', m.revenue], ['Operating expenses', m.operating], ['Net profit', m.profit], ['Outstanding all dates', m.outstanding]].map(([label, amount]) => [label, month, amount])]; }
    else rows = [['Vehicle', 'Month', 'Trips', 'Revenue AED', 'Fuel litres', 'Fuel AED', 'Water AED', 'Driver AED', 'Other AED', 'Operating AED', 'Profit AED'], ...state.vehicles.map(v => { const m = M.metrics(state, month, t => t.vehicle === v.id); return [v.plate, month, m.trips, m.revenue, m.litres, m.fuel, m.water, m.driver, m.other, m.operating, m.profit]; })];
    const csv = rows.map(row => row.map(cell => '"' + String(cell).replace(/^[=+@-]/, "'$&").replaceAll('"', '""') + '"').join(',')).join('\r\n');
    const url = URL.createObjectURL(new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' })), a = document.createElement('a');
    a.href = url; a.download = `aquafleet-${slug(reportTab)}-${month}.csv`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); toast(reportTab + ' exported.');
  }
  function navigate(name) { view = routes.includes(name) ? name : 'Dashboard'; filters.q = ''; closeDialog(); location.hash = slug(view); render(); document.querySelector('h1').closest('main').focus(); window.scrollTo(0, 0); }
  document.addEventListener('click', event => {
    const target = event.target.closest('[data-action]'); if (!target) return;
    const action = target.dataset.action, id = target.dataset.id;
    try {
      switch (action) {
        case 'nav': navigate(id); break;
        case 'menu': openDialog('Operations menu', 'Choose a workspace.', `<nav class="nav mobile-nav" aria-label="Mobile navigation">${navigation()}</nav><div class="dialog-actions">${button('Reset demo', 'reset', '', 'danger')}</div>`, true); break;
        case 'close': closeDialog(); break;
        case 'new-trip': newTripForm(); break;
        case 'trip-detail': tripDetail(id); break;
        case 'customer-detail': customerDetail(id); break;
        case 'vehicle-detail': vehicleDetail(id); break;
        case 'driver-detail': driverDetail(id); break;
        case 'costs': costsForm(id); break;
        case 'advance': mutate(() => M.advance(state, id)); tripDetail(id); toast(id + ' · ' + trip(id).status); break;
        case 'collect': collectionForm(id); break;
        case 'recharge': rechargeForm(id); break;
        case 'expense': expenseForm(); break;
        case 'source-select': sourceFilter = id; render(); break;
        case 'payment-filter': paymentFilter = id; render(); break;
        case 'report-tab': reportTab = id; render(); break;
        case 'report-nav': reportTab = id; navigate('Reports'); break;
        case 'clear-filters': filters = { q: '', status: '', vehicle: '', driver: '', customer: '', date: '', paymentType: '', month: M.MONTH, category: '' }; render(); break;
        case 'export': exportReport(); break;
        case 'reset': openDialog('Reset the AquaFleet demo?', 'This clears only AquaFleet trips and changes in this browser.', `<p>Restore the fictional starting dataset, source ledger and receipt history.</p><div class="dialog-actions">${button('Keep my changes', 'close')}${button('Reset demo data', 'confirm-reset', '', 'danger')}</div>`, true); break;
        case 'confirm-reset': state = M.seed(); save(); closeDialog(); view = 'Dashboard'; location.hash = 'dashboard'; filters = { q: '', status: '', vehicle: '', driver: '', customer: '', date: '', paymentType: '', month: M.MONTH, category: '' }; render(); toast('Demo restored to its starting data.'); break;
      }
    } catch (error) { const box = dialog.open ? dialog.querySelector('.form-error') : null; if (box) box.textContent = error.message; else toast(error.message); }
  });
  function filterChange(event) {
    const target = event.target, key = target.dataset.filter; if (!key) return;
    const selection = target.selectionStart, value = target.value; filters[key] = value; render();
    const replacement = document.querySelector(`[data-filter="${key}"]`); replacement?.focus(); if (key === 'q' && replacement) replacement.setSelectionRange(selection, selection);
  }
  document.addEventListener('input', event => { if (event.target.dataset.filter === 'q') filterChange(event); });
  document.addEventListener('change', event => {
    if (event.target.dataset.filter && event.target.dataset.filter !== 'q') filterChange(event);
    const form = event.target.closest('[data-form="trip"]'); if (!form) return;
    if (event.target.name === 'vehicle') { const v = vehicle(form.elements.vehicle.value); form.elements.driver.value = v.driver; form.elements.quantity.max = v.capacity; if (Number(form.elements.quantity.value) > v.capacity) form.elements.quantity.value = v.capacity; }
    if (event.target.name === 'customer') { const c = customer(form.elements.customer.value); form.elements.destination.value = c.location; form.elements.paymentType.value = c.type; }
    document.querySelector('#trip-estimate').textContent = `Estimated source charge: ${money(Number(form.elements.quantity.value) * source(form.elements.source.value).rate)}. Fuel estimate is excluded from actual expenses.`;
  });
  document.addEventListener('submit', event => {
    const form = event.target.closest('[data-form]'); if (!form) return; event.preventDefault();
    const data = Object.fromEntries(new FormData(form)), id = form.dataset.id;
    for (const key of ['quantity', 'amount', 'fuelEstimate', 'fuelLitres', 'fuelCost', 'driverCost', 'otherCost']) if (key in data) data[key] = Number(data[key]);
    try {
      let result;
      switch (form.dataset.form) {
        case 'trip': result = mutate(() => M.createTrip(state, data)); tripDetail(result.id); toast(result.id + ' created. Vehicle and driver assigned.'); break;
        case 'costs': mutate(() => M.recordCosts(state, id, data)); tripDetail(id); toast('Actual costs saved. The tanker is ready for dispatch.'); break;
        case 'recharge': mutate(() => M.recharge(state, id, data)); sourceFilter = id; closeDialog(); render(); toast('Recharge posted. Source balance updated.'); break;
        case 'collect': mutate(() => M.collect(state, id, data.amount, data.reference, data.date)); tripDetail(id); toast('Collection saved. Customer balance updated.'); break;
        case 'expense': mutate(() => M.addExpense(state, data)); closeDialog(); render(); toast('Fleet expense saved. Vehicle profitability updated.'); break;
      }
    } catch (error) { form.querySelector('.form-error').textContent = error.message; }
  });
  window.addEventListener('hashchange', () => { const requested = routes.find(r => slug(r) === location.hash.slice(1)); if (requested && requested !== view) { view = requested; filters.q = ''; closeDialog(); render(); } });
  render();
  if (restoreWarning) toast('Saved demo data could not be read. The fictional starting data has been restored.');
})();
